#!/usr/bin/env bash
set -euo pipefail

ROOT="$(cd "$(dirname "$0")" && pwd)"

write_icon() {
  local name="$1" data="$2"
  printf '%s' "$data" | base64 --decode > "$ROOT/$name"
}

